/**
 * English definitions from Wiktionary (generated by scripts/build-wiktionary.mjs), split
 * into one shard per first letter so only the letters a learner clicks are loaded.
 */

/** Wiktextract part-of-speech codes kept by the build script. */
export type DictPos =
  | 'noun'
  | 'verb'
  | 'adj'
  | 'adv'
  | 'pron'
  | 'prep'
  | 'conj'
  | 'intj'
  | 'det'
  | 'article'
  | 'num'
  | 'particle'
  | 'contraction'
  | 'phrase'
  | 'prep_phrase'
  | 'proverb'
  | 'abbrev';

const POS_CODES: ReadonlySet<string> = new Set<DictPos>([
  'noun',
  'verb',
  'adj',
  'adv',
  'pron',
  'prep',
  'conj',
  'intj',
  'det',
  'article',
  'num',
  'particle',
  'contraction',
  'phrase',
  'prep_phrase',
  'proverb',
  'abbrev',
]);

export function isDictPos(v: unknown): v is DictPos {
  return typeof v === 'string' && POS_CODES.has(v);
}

export interface DictSense {
  pos: DictPos;
  gloss: string;
  example?: string;
}

/** What the word card shows for one headword. */
export interface DictEntry {
  headword: string;
  /** The lemma when the clicked form is an inflection ("struggled" → "struggle"). */
  lemma?: string;
  /** Vietnamese translations from Wiktionary's tables (human-written). */
  vi: string[];
  senses: DictSense[];
}

/** One looked-up word or phrase in a sentence. */
export interface WordLookup {
  /** Indexes of the sentence words the entry covers (e.g. figure · it · out). */
  words: number[];
  entry: DictEntry;
}

/** Raw shard line fields, by headword. */
export type DictShard = ReadonlyMap<string, readonly string[]>;

/** First-letter shard name of a headword ("_" for anything not a–z). */
export function shardOf(headword: string): string {
  const c = headword.charAt(0).toLowerCase();
  return c >= 'a' && c <= 'z' ? c : '_';
}

export function parseDictShard(text: string): DictShard {
  const out = new Map<string, string[]>();
  for (const line of text.split('\n')) {
    if (!line || line.startsWith('#')) continue;
    const [head, ...fields] = line.split('\t');
    if (head) out.set(head, fields);
  }
  return out;
}

/** Senses and translations of a headword; inflected forms point to their lemma. */
export function entryOf(
  headword: string,
  get: (headword: string) => readonly string[] | undefined,
): DictEntry | null {
  const fields = get(headword);
  if (!fields) return null;
  const entry: DictEntry = { headword, vi: [], senses: [] };
  for (const f of fields) {
    const [pos, a, b] = f.split('|');
    if (pos === 'vi' && a) {
      entry.vi = a.split('; ').filter(Boolean);
      continue;
    }
    if (!isDictPos(pos) || !a) continue;
    if (a.startsWith('@')) {
      // "simple past of struggle": show the lemma's meanings instead.
      const lemma = a.slice(1);
      if (entry.lemma || lemma === headword) continue;
      const base = entryOf(lemma, (h) => (h === headword ? undefined : get(h)));
      if (!base) continue;
      entry.lemma = lemma;
      entry.senses.push(...base.senses);
      if (entry.vi.length === 0) entry.vi = base.vi;
      continue;
    }
    entry.senses.push({ pos, gloss: a, ...(b ? { example: b } : {}) });
  }
  return entry.senses.length > 0 || entry.vi.length > 0 ? entry : null;
}

/** Lower-case word as a dictionary headword: letters, digits, ' and - only. */
export function headwordOf(word: string): string {
  return word
    .toLowerCase()
    .replace(/[’‘]/g, "'")
    .replace(/^[^a-z0-9]+|[^a-z0-9]+$/g, '');
}

/** Words that can sit between a verb and its particle ("figure it out"). */
const OBJECT_PRONOUNS = new Set(['it', 'them', 'him', 'her', 'me', 'us', 'you', 'this', 'that']);

export interface Candidate {
  headword: string;
  words: number[];
}

/**
 * Headwords to try for a clicked word, best first: phrases of 4 down to 2 words around it
 * (also with the verb's lemma), separable phrasal verbs (verb + pronoun + particle), then
 * the word itself. `lemmaOf` maps an inflected verb to its base form when known.
 */
export function candidatesFor(
  words: readonly string[],
  index: number,
  lemmaOf: (headword: string) => string | undefined = () => undefined,
): Candidate[] {
  const heads = words.map(headwordOf);
  const out: Candidate[] = [];
  const seen = new Set<string>();
  const push = (headword: string, idx: number[]) => {
    if (!headword || seen.has(headword)) return;
    seen.add(headword);
    out.push({ headword, words: idx });
  };
  const variants = (i: number) => {
    const h = heads[i] ?? '';
    const lemma = lemmaOf(h);
    return lemma && lemma !== h ? [h, lemma] : [h];
  };
  for (let len = 4; len >= 2; len--) {
    for (let start = Math.max(0, index - len + 1); start <= index; start++) {
      if (start + len > heads.length) continue;
      const idx = Array.from({ length: len }, (_, k) => start + k);
      if (idx.some((i) => !heads[i])) continue;
      for (const first of variants(start)) {
        push([first, ...idx.slice(1).map((i) => heads[i])].join(' '), idx);
      }
    }
  }
  // Separable phrasal verb: verb · pronoun · particle, clicked on any of the three.
  for (let v = index - 2; v <= index; v++) {
    const p = v + 2;
    if (v < 0 || p >= heads.length || !OBJECT_PRONOUNS.has(heads[v + 1] ?? '')) continue;
    for (const verb of variants(v)) push(`${verb} ${heads[p]}`, [v, v + 1, p]);
  }
  for (const h of variants(index)) push(h, [index]);
  // "Learner's" → "learner".
  const h = heads[index] ?? '';
  if (h.endsWith("'s")) push(h.slice(0, -2), [index]);
  return out;
}

/** Content side → background: what the panel needs from the dictionary. */
export interface DictionaryAdapter {
  lookup(words: readonly string[], index: number): Promise<WordLookup | null>;
}

/**
 * Looks words up in their context, loading each first-letter shard once. `load` returns a
 * shard's text (fetched from the extension package); failures are retried next time.
 */
export function createDictionary(load: (shard: string) => Promise<string>): DictionaryAdapter {
  const shards = new Map<string, Promise<DictShard>>();
  const shard = (name: string) => {
    let p = shards.get(name);
    if (!p) {
      p = load(name).then(parseDictShard);
      p.catch(() => shards.delete(name));
      shards.set(name, p);
    }
    return p;
  };
  return {
    async lookup(words, index) {
      const clicked = headwordOf(words[index] ?? '');
      if (!clicked) return null;
      const loaded = new Map<string, DictShard>();
      const ensure = async (headwords: Iterable<string>) => {
        for (const h of headwords) {
          const name = shardOf(h);
          if (!loaded.has(name)) loaded.set(name, await shard(name));
        }
      };
      const get = (h: string) => loaded.get(shardOf(h))?.get(h);
      // Lemmas of the words around the click (for "figured it out" → "figure out").
      const around = words
        .slice(Math.max(0, index - 3), index + 4)
        .map(headwordOf)
        .filter(Boolean);
      await ensure(around);
      const lemmaOf = (h: string) => {
        for (const f of get(h) ?? []) {
          const [pos, a] = f.split('|');
          if (pos === 'verb' && a?.startsWith('@')) return a.slice(1);
        }
        return undefined;
      };
      const candidates = candidatesFor(words, index, lemmaOf);
      await ensure(candidates.map((c) => c.headword));
      for (const c of candidates) {
        const entry = entryOf(c.headword, get);
        if (entry) return { words: c.words, entry };
      }
      return null;
    },
  };
}
